function translate_address(s, o, operation):
    // Assume STLR is Segment Table Length Register
    if s >= STLR:
        raise SegmentFault("Segment number out of bounds")

    entry = ST[s] // Get segment table entry for segment s

    if not entry.valid_bit:
        raise InvalidSegmentFault("Segment not present in memory")

    if o >= entry.limit:
        raise OffsetFault("Offset out of segment bounds")

    // Protection check
    if operation == WRITE and not entry.write_permission:
        raise ProtectionFault("No write permission for segment")
    if operation == READ and not entry.read_permission:
        raise ProtectionFault("No read permission for segment")
    if operation == EXECUTE and not entry.execute_permission:
        raise ProtectionFault("No execute permission for segment")

    physical_address = entry.base_address + o
    return physical_address
